// Keeps the events of this recipe, then builds the request(s) for Discord.
const WANTED = ["member.joined", "live.session.started", "live.replay.ready", "course.published"]
const out = []
for (const item of $input.all()) {
  const msg = item.json.body ?? item.json
  if (WANTED.length && !WANTED.includes(msg.event)) continue
  const DISCORD_WEBHOOK = 'https://discord.com/api/webhooks/XXX/YYY' // channel webhook
  const APP = 'https://app.learnfloo.com' // or your space's custom domain
  const d = msg.data
  const content = {
    'member.joined': `👋 Welcome ${d.user?.name ?? ''}!`,
    'live.session.started': `🔴 **${d.session?.title}** is live now: ${APP}/${msg.space.slug}/live/${d.session?.id}`,
    'live.replay.ready': `🎬 The replay of **${d.session?.title}** is online: ${APP}/${msg.space.slug}/live/${d.session?.id}`,
    'course.published': `📚 New course: **${d.course?.title}** ${APP}${d.course?.url ?? ''}`,
  }[msg.event]
  if (content) out.push({ json: { method: 'POST', url: DISCORD_WEBHOOK, body: { content } } })
}
return out
